@gene("new", "penalty for stepping close to visible enemy champions while hurt", parents=["s4"])
def hurt_step_penalty(t: Tile) -> Num:
    here = me().pos
    p = 0
    for u in enemies():
        if u.is_champion:
            dn = dist(u.pos, t)
            dh = dist(u.pos, here)
            if dn <= 3 and dn < dh:
                p += 1.5
    return p
```

